head.b:skin:
:root {
  --color-bg: #ffffff;
  --color-text: #333333;
  --color-primary: #3498db;
  --color-accent: #e67e22;
  --font-main: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;

  /* Cores Aquarela */
  --water-blue: rgba(135, 206, 235, 0.2);
  --water-green: rgba(152, 251, 152, 0.2);
  --water-pink: rgba(255, 182, 193, 0.2);
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

/* HEADER */
.site-header {
  padding: 20px 0;
  text-align: center;
  border-bottom: 1px solid rgba(0,0,0,0.05);
}

/* HERO SECTION COM EFEITO AQUARELA */
.watercolor-bg {
  /* Múltiplos gradientes radiais para simular manchas de aquarela no CSS */
  background: 
    radial-gradient(circle at 15% 50%, var(--water-blue), transparent 40%),
    radial-gradient(circle at 85% 30%, var(--water-green), transparent 40%),
    radial-gradient(circle at 50% 80%, var(--water-pink), transparent 50%);
  background-color: var(--color-bg);
}

.hero-section {
  padding: 100px 20px;
  text-align: center;
}

.hero-section h1 {
  font-size: 3em;
  margin-bottom: 10px;
  color: #2c3e50;
}

.hero-section p {
  font-size: 1.2em;
  color: #555;
  margin-bottom: 30px;
}

.btn-primary {
  display: inline-block;
  padding: 15px 30px;
  background-color: var(--color-primary);
  color: #fff;
  text-decoration: none;
  border-radius: 30px;
  font-weight: bold;
  box-shadow: 0 4px 15px rgba(52, 152, 219, 0.3);
  transition: transform 0.3s ease, background-color 0.3s ease;
}

.btn-primary:hover {
  transform: translateY(-3px);
  background-color: #2980b9;
}

/* SERVIÇOS */
.services-section {
  padding: 60px 20px;
  text-align: center;
}

.grid-services {
  display: flex;
  grid-gap: 30px;
  justify-content: space-between;
  flex-wrap: wrap;
  margin-top: 40px;
}

.card {
  flex: 1;
  min-width: 250px;
  background: #fff;
  padding: 30px;
  border-radius: 15px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.05);
  border-bottom: 4px solid var(--color-primary);
  transition: transform 0.3s;
}

.card:hover {
  transform: translateY(-10px);
}

/* FOOTER & CONTACT */
.site-footer {
  background-color: #f9f9f9;
  padding: 50px 20px;
  text-align: center;
}

.contact-area {
  max-width: 600px;
  margin: 0 auto;
  text-align: left;
}

/* FORÇA O DESIGN NO FORMULÁRIO NATIVO DO BLOGGER */
.contact-form-widget { max-width: 100%; }
.contact-form-name, .contact-form-email, .contact-form-email-message {
  width: 100% !important;
  max-width: 100% !important;
  padding: 15px;
  margin-bottom: 15px;
  border: 1px solid #ddd;
  border-radius: 8px;
  font-family: inherit;
}
.contact-form-button-submit {
  width: 100%;
  padding: 15px;
  background-color: var(--color-accent);
  color: white;
  border: none;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
}

/* Definição da Animação Arco-Íris Suave */
@keyframes rainbow-watercolor {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Efeito de Texto Animado */
.rainbow-text {
  background: linear-gradient(to right, #ff7eb3, #ff758c, #ff7eb3, #7afcff, #feff9c, #ff7eb3);
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: rainbow-watercolor 5s linear infinite;
  font-weight: 800;
}

/* Fundo Animado Aquarela Arco-Íris */
.watercolor-animated {
  background: linear-gradient(-45deg, #fdfcfb, #e2d1c3, #f5f7fa, #c3cfe2, #e0c3fc, #fbc2eb);
  background-size: 400% 400%;
  animation: rainbow-watercolor 15s ease infinite;
  position: relative;
}

/* Overlay para suavizar o fundo e manter o texto legível */
.watercolor-animated::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(255, 255, 255, 0.6); /* Deixa as cores pastel */
  z-index: 1;
}

.watercolor-animated .container {
  position: relative;
  z-index: 2; /* Garante que o texto fique acima do overlay */
}

body.script:
//
document.addEventListener('DOMContentLoaded', () => {
  // Efeito de rolagem suave para links internos
  const links = document.querySelectorAll('a[href^="#"]');

  links.forEach(link => {
    link.addEventListener('click', function(e) {
      e.preventDefault();
      const targetId = this.getAttribute('href');
      const targetElement = document.querySelector(targetId);

      if (targetElement) {
        window.scrollTo({
          top: targetElement.offsetTop - 30, // Margem de respiro
          behavior: 'smooth'
        });
      }
    });
  });
});
//
